  str_pet_equip_name_1602311 = "Pedang Darah, \"Gelombang Merah\"",
  str_pet_equip_name_1502321 = "Pedang Darah Suci",
  str_pet_equip_name_1602331 = "Sparkling Reverie",
  str_pet_equip_name_1602341 = "Astrumnox",
